export class CommandCoordinator {
  constructor(_state,env){this.env=env;this.queue=Promise.resolve()}
  fetch(request){const work=this.queue.then(async()=>{const body=await request.json();return apiResponse(await executeCommand(this.env,body.owner,body.action,body.input,body.requestId))});this.queue=work.catch(()=>undefined);return work.catch(error=>errorResponse(error))}
}

function cors(env,request){const origin=request.headers.get('origin')||'',configured=String(env.API_ALLOWED_ORIGIN||'').trim(),headers={'access-control-allow-headers':'authorization,content-type','access-control-allow-methods':'GET,POST,PATCH,DELETE,PUT,OPTIONS','vary':'Origin'};if(!configured)headers['access-control-allow-origin']='*';else if(origin===configured)headers['access-control-allow-origin']=origin;return headers}
function withHeaders(response,headers){const output=new Headers(response.headers);Object.entries(headers).forEach(([key,value])=>output.set(key,value));return new Response(response.body,{status:response.status,statusText:response.statusText,headers:output})}
function htmlResponse(html, status = 200){return new Response(html,{status,headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store'}})}
function escapeHtml(value){return String(value||'').replace(/[&<>\"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
async function body(request){try{return await request.json()}catch{throw new ApiError('VALIDATION_ERROR','请求数据格式无效')}}
function bearer(request){const value=request.headers.get('authorization')||'';return value.startsWith('Bearer ')?value.slice(7):''}
async function owner(request,env){const openId=await verifySession(bearer(request),env.SESSION_SECRET);ensure(env.OWNER_OPENID&&openId===env.OWNER_OPENID,'UNAUTHORIZED','当前微信账号无管理权限',403);return openId}

async function login(request,env){const input=await body(request),code=text(input.code,'登录凭证',200);ensure(env.WX_APP_ID&&!env.WX_APP_ID.startsWith('replace-'),'CONFIGURATION_ERROR','微信 AppID 尚未配置',500);ensure(env.WX_APP_SECRET,'CONFIGURATION_ERROR','微信 AppSecret 尚未配置',500);const url=new URL('https://api.weixin.qq.com/sns/jscode2session');url.searchParams.set('appid',env.WX_APP_ID);url.searchParams.set('secret',env.WX_APP_SECRET);url.searchParams.set('js_code',code);url.searchParams.set('grant_type','authorization_code');const response=await fetch(url.toString());const session=await response.json();ensure(session.openid,'UNAUTHORIZED',session.errmsg||'微信登录失败',401);const configured=Boolean(env.OWNER_OPENID&&!env.OWNER_OPENID.startsWith('replace-'));if(!configured)return{openId:session.openid,authorized:false,configured:false};if(session.openid!==env.OWNER_OPENID)return{openId:session.openid,authorized:false,configured:true};return{openId:session.openid,authorized:true,configured:true,token:await signSession(session.openid,env.SESSION_SECRET)}}

async function manage(request,env){const currentOwner=await owner(request,env),input=await body(request),action=text(input.action,'action',80);if(WRITE_ACTIONS.has(action)){const durableId=env.COMMAND_COORDINATOR.idFromName(currentOwner),stub=env.COMMAND_COORDINATOR.get(durableId);const response=await stub.fetch('https://coordinator/command',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({owner:currentOwner,action,input:input.input||{},requestId:input.requestId||''})});const value=await response.json();if(!value.ok)throw new ApiError(value.error.code,value.error.message,response.status,value.error.details);return value.data}return executeRead(env,currentOwner,action,input.input||{},new URL(request.url).origin,bearer(request))}

async function createUpload(request,env){const currentOwner=await owner(request,env),input=await body(request),type=input.type;ensure(['image','video'].includes(type),'VALIDATION_ERROR','媒体类型无效');const limit=type==='video'?VIDEO_LIMIT:IMAGE_LIMIT,size=Number(input.size);ensure(Number.isSafeInteger(size)&&size>0&&size<=limit,'VALIDATION_ERROR','媒体文件超过大小限制');const requestId=text(input.requestId,'requestId',100),assetId=(await sha256(`${currentOwner}:${requestId}:media`)).slice(0,36),existing=await first(env,'SELECT * FROM media_assets WHERE id=? AND owner_open_id=?',assetId,currentOwner);if(existing){ensure(existing.type===type&&Number(existing.size)===size,'CONFLICT','上传请求号已用于其他媒体',409);return{assetId,uploadId:existing.upload_id,partSize:PART_SIZE,type:existing.type,size:existing.size}}const fileName=text(input.fileName,'文件名',200),extension=(fileName.split('.').pop()||'bin').toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,8)||'bin',imageExtensions=new Set(['jpg','jpeg','png','webp','gif']),videoExtensions=new Set(['mp4','mov','m4v']);ensure(!(type==='image'&&videoExtensions.has(extension))&&!(type==='video'&&imageExtensions.has(extension)),'VALIDATION_ERROR','媒体类型与文件扩展名不匹配');const key=`private/${currentOwner}/${assetId}.${extension}`,mime=type==='video'?(extension==='mov'?'video/quicktime':'video/mp4'):({jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',gif:'image/gif'}[extension]||'application/octet-stream'),uploadId=await cosCreateMultipartUpload(env,key,mime),now=nowIso();await env.DB.prepare('INSERT INTO media_assets (id,owner_open_id,type,size,file_name,object_key,upload_id,mime,source,status,revision,created_at,updated_at,deleted_at,deleted_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(assetId,currentOwner,type,size,fileName,key,uploadId,mime,'LOCAL_UPLOAD','PENDING',1,now,now,null,null).run();return{assetId,uploadId,partSize:PART_SIZE,type,size}}

async function uploadPart(request,env,assetId,partNumber){const currentOwner=await owner(request,env),asset=await first(env,'SELECT * FROM media_assets WHERE id=? AND owner_open_id=? AND status=? AND deleted_at IS NULL',assetId,currentOwner,'PENDING');ensure(asset,'NOT_FOUND','上传任务不存在',404);const uploadId=new URL(request.url).searchParams.get('uploadId');ensure(uploadId&&uploadId===asset.upload_id,'UNAUTHORIZED','上传任务无效',403);const part=Number(partNumber);ensure(Number.isInteger(part)&&part>=1&&part<=100,'VALIDATION_ERROR','分片编号无效');const chunk=await request.arrayBuffer();ensure(chunk.byteLength>0&&chunk.byteLength<=PART_SIZE,'VALIDATION_ERROR','分片大小无效');const etag=await cosUploadPart(env,asset.object_key,uploadId,part,chunk);return{partNumber:part,etag}}

async function completeUpload(request,env,assetId){const currentOwner=await owner(request,env),input=await body(request),asset=await first(env,'SELECT * FROM media_assets WHERE id=? AND owner_open_id=? AND deleted_at IS NULL',assetId,currentOwner);ensure(asset,'NOT_FOUND','上传任务不存在',404);if(asset.status==='COMMITTED')return mediaAssetView(request,env,asset);ensure(input.uploadId===asset.upload_id,'UNAUTHORIZED','上传任务无效',403);const expectedParts=Math.ceil(asset.size/PART_SIZE);ensure(Array.isArray(input.parts)&&input.parts.length===expectedParts,'VALIDATION_ERROR','上传分片数量无效');const parts=input.parts.map(item=>({partNumber:Number(item.partNumber),etag:text(item.etag,'etag',200)})).sort((a,b)=>a.partNumber-b.partNumber);ensure(parts.every((item,index)=>item.partNumber===index+1),'VALIDATION_ERROR','上传分片编号必须连续');await cosCompleteMultipartUpload(env,asset.object_key,asset.upload_id,parts);const now=nowIso();await env.DB.prepare('UPDATE media_assets SET status=?,revision=revision+1,updated_at=? WHERE id=?').bind('COMMITTED',now,asset.id).run();return mediaAssetView(request,env,{...asset,status:'COMMITTED',revision:asset.revision+1,updated_at:now})}

async function mediaAssetView(request,env,asset){const expires=Math.floor(Date.now()/86400000)*86400+86400,signature=await mediaSignature(asset.id,expires,env.MEDIA_SIGNING_SECRET);return{assetId:asset.id,type:asset.type,size:asset.size,fileID:`${new URL(request.url).origin}/api/media/${asset.id}?expires=${expires}&signature=${signature}`}}

async function mediaFile(request,env,assetId,ctx){const url=new URL(request.url),expires=Number(url.searchParams.get('expires')),signature=url.searchParams.get('signature')||'',variant=url.searchParams.get('variant')||'',range=request.headers.get('range')||'';ensure(expires>Math.floor(Date.now()/1000)&&expires<Math.floor(Date.now()/1000)+86400,'UNAUTHORIZED','媒体地址已失效',401);ensure(constantTimeEqual(await mediaSignature(assetId,expires,env.MEDIA_SIGNING_SECRET),signature),'UNAUTHORIZED','媒体签名无效',401);ensure(!variant||variant==='thumbnail','VALIDATION_ERROR','媒体规格无效');const cacheKey=new Request(`${url.origin}/_media-cache/${encodeURIComponent(assetId)}${variant?`?variant=${variant}`:''}`),cache=typeof caches==='undefined'||range?null:caches.default;if(cache){const cached=await cache.match(cacheKey);if(cached)return cached}const asset=await first(env,'SELECT * FROM media_assets WHERE id=? AND status=? AND deleted_at IS NULL',assetId,'COMMITTED');ensure(asset,'NOT_FOUND','媒体不存在',404);const object=await cosGetObject(env,asset.object_key,range);const headers=new Headers();['content-type','content-length','content-range','etag','last-modified'].forEach(name=>{const value=object.headers.get(name);if(value)headers.set(name,value)});headers.set('accept-ranges','bytes');headers.set('cache-control','public, max-age=86400');const response=new Response(object.body,{status:object.status,headers});if(cache&&response.ok){const task=cache.put(cacheKey,response.clone());if(ctx&&typeof ctx.waitUntil==='function')ctx.waitUntil(task);else await task}return response}

async function importMedia(request,env){const currentOwner=await owner(request,env),input=await body(request),requestId=text(input.requestId,'requestId',100),assetId=(await sha256(`${currentOwner}:${requestId}:url`)).slice(0,36),existing=await first(env,'SELECT * FROM media_assets WHERE id=? AND owner_open_id=?',assetId,currentOwner);if(existing&&existing.status==='COMMITTED')return mediaAssetView(request,env,existing);const downloaded=await downloadMedia(text(input.url,'URL',2048)),key=`private/${currentOwner}/${assetId}.${downloaded.extension}`;await cosPutObject(env,key,downloaded.buffer,downloaded.mime);const now=nowIso();await env.DB.prepare('INSERT OR REPLACE INTO media_assets (id,owner_open_id,type,size,file_name,object_key,upload_id,mime,source,status,revision,created_at,updated_at,deleted_at,deleted_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(assetId,currentOwner,downloaded.type,downloaded.buffer.byteLength,`import.${downloaded.extension}`,key,null,downloaded.mime,'URL_IMPORT','COMMITTED',1,now,now,null,null).run();return mediaAssetView(request,env,{id:assetId,type:downloaded.type,size:downloaded.buffer.byteLength})}

async function downloadMedia(raw,redirects=0){ensure(redirects<=3,'MEDIA_REJECTED','重定向次数过多');const url=new URL(raw);ensure(url.protocol==='https:'&&!url.username&&!url.password&&!url.port&&!isUnsafeHostname(url.hostname),'MEDIA_REJECTED','媒体地址不安全');const response=await fetch(url.toString(),{redirect:'manual',headers:{accept:'image/*,video/mp4','user-agent':'ParrotPro/1.0'},signal:AbortSignal.timeout(20000)});if(response.status>=300&&response.status<400&&response.headers.get('location'))return downloadMedia(new URL(response.headers.get('location'),url).toString(),redirects+1);ensure(response.ok,'MEDIA_REJECTED','远程媒体不可用');const declared=Number(response.headers.get('content-length')||0);ensure(!declared||declared<=URL_VIDEO_LIMIT,'MEDIA_REJECTED','URL媒体文件超过大小限制');const buffer=await response.arrayBuffer();const detected=sniff(buffer,URL_IMAGE_LIMIT,URL_VIDEO_LIMIT);ensure(detected&&buffer.byteLength<=detected.limit,'MEDIA_REJECTED','URL图片需小于4MB，视频需小于20MB');return{buffer,...detected}}

