async function route(request,env){const url=new URL(request.url),path=url.pathname;if(request.method==='OPTIONS')return new Response(null,{status:204});if(path==='/api/health')return apiResponse({status:'ok'});if(path==='/api/auth/login'&&request.method==='POST')return apiResponse(await login(request,env));if(path==='/api/session'&&request.method==='GET'){const openId=await owner(request,env);return apiResponse({openId,authorized:true,configured:true})}if(path==='/api/manage'&&request.method==='POST')return apiResponse(await manage(request,env));if(path==='/api/media/multipart/create'&&request.method==='POST')return apiResponse(await createUpload(request,env));let match=path.match(/^\/api\/media\/multipart\/([^/]+)\/parts\/(\d+)$/);if(match&&request.method==='PUT')return apiResponse(await uploadPart(request,env,match[1],match[2]));match=path.match(/^\/api\/media\/multipart\/([^/]+)\/complete$/);if(match&&request.method==='POST')return apiResponse(await completeUpload(request,env,match[1]));if(path==='/api/media/import'&&request.method==='POST')return apiResponse(await importMedia(request,env));match=path.match(/^\/api\/media\/([^/]+)$/);if(match&&request.method==='GET')return mediaFile(request,env,match[1]);match=path.match(/^\/share\/(.+)$/);if(match&&request.method==='GET')return publicSharePageV3(request,env,decodeURIComponent(match[1]));match=path.match(/^\/api\/public\/shares\/(.+)$/);if(match&&request.method==='GET')return apiResponse(await publicShare(request,env,decodeURIComponent(match[1])));throw new ApiError('NOT_FOUND','接口不存在',404)}

export default {async fetch(request,env){const headers=cors(env,request);try{return withHeaders(await route(request,env),headers)}catch(error){console.error('[worker]',error);return withHeaders(errorResponse(error),headers)}},async scheduled(_event,env,ctx){ctx.waitUntil(cleanup(env))}}

async function cleanup(env){const cutoff=new Date(Date.now()-86400000).toISOString();await env.DB.prepare('DELETE FROM share_tokens WHERE expires_at<=? OR revoked_at IS NOT NULL OR deleted_at IS NOT NULL').bind(nowIso()).run();const assets=await all(env,"SELECT * FROM media_assets WHERE (status='PENDING' AND created_at<?) OR (status='COMMITTED' AND created_at<? AND NOT EXISTS (SELECT 1 FROM parrots,json_each(parrots.media_json) WHERE json_extract(json_each.value,'$.assetId')=media_assets.id) AND NOT EXISTS (SELECT 1 FROM sales_records,json_each(sales_records.media_json) WHERE json_extract(json_each.value,'$.assetId')=media_assets.id)) LIMIT 100",cutoff);for(const asset of assets){try{if(asset.status==='PENDING'&&asset.upload_id)await cosAbortMultipartUpload(env,asset.object_key,asset.upload_id);else await cosDeleteObject(env,asset.object_key);await env.DB.prepare('DELETE FROM media_assets WHERE id=?').bind(asset.id).run()}catch(error){console.error('[cleanup]',asset.id,error)}}}
