async function createHatching(env,owner,input,requestId){ const male=await owned(env,'parrots',text(input.maleId,'maleId',80),owner),female=await owned(env,'parrots',text(input.femaleId,'femaleId',80),owner); revisionCheck(male,input.maleRevision); revisionCheck(female,input.femaleRevision); ensure(male.gender==='MALE'&&female.gender==='FEMALE','INVALID_STATE','孵化父母必须为公鸟和母鸟'); const breeders=male.status===STATUS.BREEDER&&female.status===STATUS.BREEDER,paired=male.status===STATUS.PAIRED&&female.status===STATUS.PAIRED&&male.active_pair_id&&male.active_pair_id===female.active_pair_id; ensure(breeders||paired,'INVALID_STATE','父母鸟状态不允许启动孵化'); const duplicate=await first(env,'SELECT id FROM hatching_records WHERE owner_open_id=? AND male_id=? AND female_id=? AND status=? AND deleted_at IS NULL',owner,male.id,female.id,'INCUBATING'); ensure(!duplicate,'INVALID_STATE','该组合已有进行中的孵化任务'); const now=nowIso(),statements=[]; let pairId,pairRevision=1,pairedAt=now;if(paired){ const pair=await owned(env,'breeding_pairs',male.active_pair_id,owner); ensure(pair.status==='ACTIVE','INVALID_STATE','配对状态异常'); if(input.pairRevision!=null)revisionCheck(pair,input.pairRevision); pairId=pair.id;pairRevision=pair.revision+1;pairedAt=pair.paired_at;statements.push(statement(env,'UPDATE breeding_pairs SET status=?,revision=?,updated_at=? WHERE id=?','INCUBATING',pairRevision,now,pairId)) }else{ pairId=id();statements.push(statement(env,'INSERT INTO breeding_pairs (id,owner_open_id,male_id,female_id,status,paired_at,ended_at,end_reason,revision,created_at,updated_at,deleted_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',pairId,owner,male.id,female.id,'INCUBATING',now,null,null,1,now,now,null)) } const recordId=id(),eggs=integer(input.eggs,'蛋数量',1,100),species=text(input.species,'品种',60),startDate=dateOnly(input.startDate,'开始日期'),record={id:recordId,owner_open_id:owner,pair_id:pairId,male_id:male.id,female_id:female.id,male_ring_number:male.ring_number,female_ring_number:female.ring_number,species,start_date:startDate,eggs,hatched:0,status:'INCUBATING',completed_at:null,revision:1,created_at:now,updated_at:now,deleted_at:null,deleted_by:null};statements.push(statement(env,'INSERT INTO hatching_records (id,owner_open_id,pair_id,male_id,female_id,male_ring_number,female_ring_number,species,start_date,eggs,hatched,status,completed_at,revision,created_at,updated_at,deleted_at,deleted_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',...Object.values(record)));statements.push(statement(env,'UPDATE parrots SET status=?,active_pair_id=?,paired_at=?,revision=revision+1,updated_at=? WHERE id IN (?,?)',STATUS.INCUBATING,pairId,pairedAt,now,male.id,female.id));statements.push(auditStatement(env,owner,'hatching.create','hatchingRecord',recordId,requestId,null,record));return {data:{id:recordId,revision:1},statements} }

async function finishHatching(env,owner,input,requestId,deleting){ const record=await owned(env,'hatching_records',text(input.id,'id',80),owner); revisionCheck(record,input.revision); const now=nowIso(),statements=[]; if(record.status==='INCUBATING'){ const pair=await owned(env,'breeding_pairs',record.pair_id,owner); ensure(pair.status==='INCUBATING','INVALID_STATE','配对状态与孵化任务不一致'); statements.push(...await closePair(env,owner,pair,deleting?'HATCHING_CANCELLED':'HATCHING_COMPLETED',requestId,now)) }else if(!deleting)throw new ApiError('INVALID_STATE','孵化任务已经完成'); if(deleting){ statements.push(statement(env,'DELETE FROM hatching_records WHERE id=? AND owner_open_id=?',record.id,owner),auditStatement(env,owner,'hatching.delete','hatchingRecord',record.id,requestId,record,{deleted:true})); return {data:{id:record.id,deleted:true},statements} } const next={...record,status:'COMPLETED',completed_at:now,revision:record.revision+1,updated_at:now};statements.push(statement(env,'UPDATE hatching_records SET status=?,completed_at=?,revision=?,updated_at=? WHERE id=?','COMPLETED',now,next.revision,now,record.id));statements.push(auditStatement(env,owner,'hatching.complete','hatchingRecord',record.id,requestId,record,next));return {data:{id:record.id,revision:next.revision},statements} }

export async function executeRead(env,owner,action,input,baseUrl,sessionToken){
  if(action==='parrots.list'){ const rows=await all(env,'SELECT * FROM parrots WHERE owner_open_id=? AND deleted_at IS NULL ORDER BY created_at DESC',owner); return {items:await Promise.all(rows.map(row=>serializeParrot(env,row,env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken))),nextCursor:null} }
  if(action==='parrots.get'){ return serializeParrot(env,await owned(env,'parrots',text(input.id,'id',80),owner),env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken) }
  if(action==='breeding.listActive'){ const pairs=await all(env,"SELECT * FROM breeding_pairs WHERE owner_open_id=? AND deleted_at IS NULL AND status IN ('ACTIVE','INCUBATING') ORDER BY paired_at DESC",owner),result=[]; for(const pair of pairs){ const male=await owned(env,'parrots',pair.male_id,owner),female=await owned(env,'parrots',pair.female_id,owner); result.push({id:pair.id,maleId:pair.male_id,femaleId:pair.female_id,status:pair.status,pairedAt:pair.paired_at,revision:pair.revision,createdAt:pair.created_at,updatedAt:pair.updated_at,male:await serializeParrot(env,male,env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken),female:await serializeParrot(env,female,env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken)}) } return result }
  if(action==='hatching.list'){ const rows=await all(env,'SELECT * FROM hatching_records WHERE owner_open_id=? AND deleted_at IS NULL ORDER BY start_date DESC,created_at DESC',owner); return {items:rows.map(row=>({id:row.id,pairId:row.pair_id,maleId:row.male_id,femaleId:row.female_id,maleSnapshot:{ringNumber:row.male_ring_number},femaleSnapshot:{ringNumber:row.female_ring_number},species:row.species,startDate:row.start_date,eggs:row.eggs,hatched:row.hatched,status:row.status,revision:row.revision,createdAt:row.created_at,updatedAt:row.updated_at})),nextCursor:null} }
  if(action==='sales.list'){ const rows=await all(env,'SELECT * FROM sales_records WHERE owner_open_id=? AND deleted_at IS NULL ORDER BY sale_date DESC,created_at DESC',owner),items=[]; for(const row of rows){items.push({id:row.id,parrotId:row.parrot_id,parrotSnapshot:{species:row.species,ringNumber:row.ring_number,gender:row.gender,birthDate:row.birth_date,media:await mediaItems(env,parseJson(row.media_json,[]),env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken)},buyer:row.buyer,buyerContact:row.buyer_contact,saleDate:row.sale_date,priceCents:row.price_cents,status:row.status,returnReason:row.return_reason,followUpStatus:row.follow_up_status,revision:row.revision,createdAt:row.created_at})} return {items,nextCursor:null} }
  if(action==='shares.list')return (await all(env,'SELECT token_hash AS id,parrot_id AS parrotId,expires_at AS expiresAt,revoked_at AS revokedAt,created_at AS createdAt FROM share_tokens WHERE owner_open_id=? AND deleted_at IS NULL ORDER BY created_at DESC',owner))
  if(action==='dashboard.get')return dashboard(env,owner)
  throw new ApiError('NOT_FOUND','接口不存在',404)
}

async function dashboard(env,owner){ const parrots=await all(env,'SELECT status,species FROM parrots WHERE owner_open_id=? AND deleted_at IS NULL',owner),sales=await all(env,'SELECT status,price_cents,sale_date FROM sales_records WHERE owner_open_id=? AND deleted_at IS NULL',owner),stats={total:parrots.length,forSale:0,sold:0,returned:0,breeder:0,paired:0,incubating:0,revenueCents:0,salesTotal:sales.length,returnRate:0};const keys={FOR_SALE:'forSale',SOLD:'sold',RETURNED:'returned',BREEDER:'breeder',PAIRED:'paired',INCUBATING:'incubating'};parrots.forEach(item=>{if(keys[item.status])stats[keys[item.status]]++});const valid=sales.filter(item=>item.status==='COMPLETED');stats.revenueCents=valid.reduce((sum,item)=>sum+item.price_cents,0);stats.returnRate=sales.length?Math.round(sales.filter(item=>item.status==='RETURNED').length/sales.length*100):0;const mix={};parrots.forEach(item=>mix[item.species]=(mix[item.species]||0)+1);const species=Object.entries(mix).map(([name,count])=>({name,count,percent:parrots.length?Math.round(count/parrots.length*100):0})).sort((a,b)=>b.count-a.count).slice(0,5);const now=new Date(),trend=[];for(let offset=5;offset>=0;offset--){const date=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()-offset,1)),month=`${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}`,monthSales=valid.filter(item=>item.sale_date.startsWith(month));trend.push({month,revenueCents:monthSales.reduce((sum,item)=>sum+item.price_cents,0),volume:monthSales.length})}return {stats,species,trend} }
